save(326,dict(paragraphs=["Mitra Samal is a Bhubaneswar-based poet and writer with a background in software consulting. Her work includes poetry, stories and literary interviews, and her collections include ‘Beginning’ and ‘Silence Has a Sound’. Her poems and prose have appeared in journals including Muse India, Madras Courier, Borderless and The Chakkar.","Her Kabita Live poems bring together public freedom and the comforts of everyday life. ‘Remember Freedom’ insists on the right to speak, love and live without fear, using a recurring phrase to keep that possibility alive. ‘Silent Streets’ listens to children, evening prayers and faint bells: its quiet is inhabited, a shared refuge rather than an empty place."],sources=[source('The Chakkar: Mitra Samal','https://www.thechakkar.com/mitra-samal',['Bhubaneswar writer and former IT consultant; journal work and literary interviews; Silence Has a Sound published by Om Books in 2026.']),source('Setu: Poetry by Mitra Samal','https://www.setumag.com/2022/02/poetry-mitra-samal.html',['Earlier software career, Beginning collection and journal publications; identity bridge to captured biography.']),source('Om Books International: new releases','https://www.ombooksinternational.com/product-category/new-releases/',['Publisher catalogue lists Silence Has a Sound by Mitra Samal.']),source('Scroll: review of Silence Has a Sound','https://scroll.in/article/1093806/silence-has-a-sound-mitra-samals-direct-articulation-in-her-poems-ensures-emotional-intimacy',['Verified book and publisher; July 2026 review available.'])],books=[dict(title='Silence Has a Sound',detail='Poetry · Om Books International, 2026 · Read the review',url='https://scroll.in/article/1093806/silence-has-a-sound-mitra-samals-direct-articulation-in-her-poems-ensures-emotional-intimacy')],identity_match='Matching software background, Bhubaneswar, journal publications and Beginning across captured record, Setu and Chakkar. Latest Chakkar describes IT role as former; prose uses background rather than current employment.',poems_read=[dict(id=399,title='Remember Freedom',basis='Full English original, five stanzas: refrain, borders, fear-free speech and love, spring in winter and freedom of mind.'),dict(id=631,title='Silent Streets',basis='Full English original: small-town dusk, passersby, children, prayers, bells, mountains and hope.')],limitations=['Publisher item click failed; working independent review used as book link. Current career phrasing reconciles older software biography with newer former-IT description.'],next_action='Independent author/editor factual review.'))
